const menu=document.querySelector('#menu'),nav=document.querySelector('#navigation');menu?.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'×':'☰'});nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='☰'}));const video=document.querySelector('.statement video'),control=document.querySelector('#video-toggle');if(matchMedia('(prefers-reduced-motion: reduce)').matches){video?.pause();if(control)control.textContent='▶'}control?.addEventListener('click',()=>{if(video.paused){video.play().catch(()=>{});control.textContent='Ⅱ';control.setAttribute('aria-label','หยุดวิดีโอ')}else{video.pause();control.textContent='▶';control.setAttribute('aria-label','เล่นวิดีโอ')}});
